  try {
    g(repoRoot, ['rev-parse', '--git-dir']);
  } catch (err) {
    return { branch: b, alive: false, reason: 'repo error: ' + err.message, error: true };
  }

  // --- (2) Local branch exists? ---
  try {
    g(repoRoot, ['rev-parse', '--verify', '--quiet', 'refs/heads/' + b]);
    return { branch: b, alive: true, reason: 'local branch exists' };
  } catch (_) { /* not local, continue */ }

  // --- (3) Remote branch exists on origin? ---
  try {
    g(repoRoot, ['rev-parse', '--verify', '--quiet', 'origin/' + b]);
    return { branch: b, alive: true, reason: 'remote branch exists (origin)' };
  } catch (_) { /* not on origin, continue */ }

  // --- (4) Is the branch's tip already reachable from the default branch? ---
  const sha = discoverTipCommit(g, repoRoot, b);
  if (!sha) {
    return { branch: b, alive: false, reason: 'branch gone, not on main: work would be lost' };
  }

  // Try main, then master (this repo defaults to master per src/git-runner.js)
  for (const candidate of ['main', 'master']) {
    try {
      g(repoRoot, ['merge-base', '--is-ancestor', sha, candidate]);
      return { branch: b, alive: true, reason: 'branch gone, work already on ' + candidate };
    } catch (_) { /* not an ancestor of this candidate */ }
  }

  return { branch: b, alive: false, reason: 'branch gone, not on main: work would be lost' };
}
```

### 3a. Helper: `discoverTipCommit`

Since the branch is gone locally and on origin, we try two discovery strategies (matching the spec's "if discoverable via `git log --all --grep`"):

```js
function discoverTipCommit(g, repoRoot, branch) {
  // Strategy 1: maybe it's a tag or a detached ref
  try {
    return g(repoRoot, ['rev-parse', '--verify', '--quiet', branch]).trim();
  } catch (_) { /* not a direct ref */ }

  // Strategy 2: search all commit messages for the branch name
  try {
    const out = g(repoRoot, [
      'log', '--all', '--oneline',
      '--grep=' + branch,
      '--format=%H', '-n', '1',
    ]).trim();
    if (/^[0-9a-f]{40}$/i.test(out)) return out;
  } catch (_) { /* no match */ }

  return null;
}
```

> **Note:** `git log --all --grep` matches commit *messages*, not branch names. This is the best-effort discovery the spec calls for; if the branch was deleted and its commits were never merged, this will return `null` and the function correctly reports "work would be lost." Verify this is the intended semantics with the task author if stricter discovery (e.g., `git reflog`) is desired.

## 4. Implement the CLI `main()`

Mirror the CLI pattern in `src/dead-process-check.js:382-385` (the `if (require.main === module) { main(); }` guard) and the JSON-on-stdout pattern:

```js
function main() {
  const argv = process.argv.slice(2);
  let branch = null;
  let repo = null;

  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--branch' && i + 1 < argv.length) { branch = argv[++i]; }
    else if (argv[i] === '--repo' && i + 1 < argv.length) { repo = argv[++i]; }
  }

  if (!branch || !repo) {
    process.stdout.write(JSON.stringify({ branch, alive: false, reason: 'missing --branch or --repo' }) + '\n');
    process.exit(2);
  }

  const result = checkBranchLiveness(repo, branch);
  process.stdout.write(JSON.stringify(result) + '\n');

  if (result.error === true) process.exit(2);
  process.exit(result.alive ? 0 : 1);
}

module.exports = { checkBranchLiveness };

if (require.main === module) {
  main();
}
```

Exit-code contract:
| Condition | Exit code |
|---|---|
| `alive === true` | **0** |
| `alive === false`, no `error` | **1** |
| `error === true` (operational) | **2** |

